function adminMessageCard(){const items=adminDemoMessages.filter(item=>!adminMessageFlags(item.id).archived),unread=items.filter(item=>!adminMessageFlags(item.id).read).length;return `<h2>${unread} message(s) non lu(s)</h2><p class="sp-card-note">Messages fictifs de la simulation locale.</p><ul class="sp-message-list">${items.slice(0,4).map(item=>`<li><button data-admin="message-open" data-value="${esc(item.id)}">${esc(item.title)}</button></li>`).join('')}</ul><button data-admin="navigate" data-value="Admin messages">Afficher tout</button>`}
