  const title=panel==='notifications'?'Notifications':panel==='settings'?'Paramètres':'Vous avez besoin d’aide ?';
  return `<div class="sp-header-overlay"><aside class="sp-header-panel" role="dialog" aria-modal="true" aria-labelledby="sp-header-title"><div class="sp-panel-head"><h2 id="sp-header-title">${title}</h2><button data-admin="header-close" aria-label="Fermer">×</button></div>${body}</aside></div>`;
