const siteMemberSections=[['owners','Propriétaires','Propriétaire'],['members','Membres','Membre'],['admins','Administrateurs de site','Administrateur de site'],['siteOwners','Propriétaires du site','Propriétaire du site'],['siteMembers','Membres du site','Membre du site'],['visitors','Visiteurs du site','Visiteur']];
