const siteViews=[['all','Tous les sites'],['teams','Sites connectés à Teams'],['group','Sites du Groupe Microsoft 365'],['no-group','Sites sans groupe'],['classic','Sites classiques'],['largest','Sites les plus volumineux'],['inactive','Sites les moins actifs'],['popular','Sites partagés les plus populaires'],['scripts','Custom script allowed sites']];
function siteHasMicrosoftGroup(site){if(typeof site.groupConnected==='boolean')return site.groupConnected;if(/classique|classic/i.test(site.template||''))return false;return !isCommunicationSite(site)}
function siteInView(site,view){switch(view){case 'teams':return !!site.teams;case 'group':return siteHasMicrosoftGroup(site);case 'no-group':return !siteHasMicrosoftGroup(site);case 'classic':return /classique|classic/i.test(site.template||'');case 'inactive':return !!site.activity;case 'popular':return Number.isFinite(site.sharingPopularity);case 'scripts':return site.scripts==='allowed';default:return true}}
function customSiteViews(){return Array.isArray(db.adminCustomSiteViews)?db.adminCustomSiteViews.filter(view=>view&&typeof view.id==='string'&&typeof view.name==='string'):[]}
function applyCustomSiteView(view){if(!view||!siteViews.some(([id])=>id===view.baseView))return false;state.adminSiteView=view.baseView;state.adminCustomSiteViewId=view.id;state.adminTeamsFilter=['connected','disconnected'].includes(view.teamsFilter)?view.teamsFilter:'';state.adminHubFilter=typeof view.hubFilter==='string'?view.hubFilter:'';state.adminActivityFilter=view.activityFilter==='last30'?'last30':'';state.adminOwnerFilters=Array.isArray(view.owners)?view.owners.filter(value=>typeof value==='string'):[];state.adminTemplateFilters=Array.isArray(view.templates)?view.templates.filter(value=>typeof value==='string'):[];state.adminSiteSort=[...sortableSiteColumns,'sharingPopularity'].includes(view.sort)?view.sort:'name';state.adminSiteSortDir=view.sortDir==='desc'?'desc':'asc';state.adminViewColumnOverride=structuredClone(view.columns||{});state.adminQuery='';state.adminSitePage=1;state.adminSelected=null;state.adminChecked=[];return true}
function applyStandardSiteView(id){if(!siteViews.some(([key])=>key===id))return false;state.adminSiteView=id;state.adminCustomSiteViewId='';state.adminViewColumnOverride=null;state.adminTeamsFilter='';state.adminHubFilter='';state.adminActivityFilter='';state.adminOwnerFilters=[];state.adminTemplateFilters=[];state.adminSitePage=1;state.adminSelected=null;state.adminChecked=[];state.adminSiteSort=id==='largest'?'storage':id==='inactive'?'activity':id==='popular'?'sharingPopularity':'name';state.adminSiteSortDir=['largest','popular'].includes(id)?'desc':'asc';return true}
function siteViewMenu(){const custom=customSiteViews(),active=custom.find(view=>view.id===state.adminCustomSiteViewId),current=siteViews.find(([id])=>id===state.adminSiteView)||siteViews[0],defaultKey=active?active.id:'builtin:'+current[0];return `<div class="sp-view-select"><button data-admin="site-view-menu" aria-expanded="${!!state.adminSiteViewMenu}">${esc(active?.name||current[1])} ⌄</button>${state.adminSiteViewMenu?`<div class="sp-view-menu" role="menu"><strong>Affichages standard</strong>${siteViews.map(([id,label])=>`<button role="menuitemradio" aria-checked="${!active&&current[0]===id}" data-admin="site-view" data-value="${id}">${esc(label)}${db.adminDefaultSiteView==='builtin:'+id?' · Par défaut':''}</button>`).join('')}${custom.length?`<strong>Affichages personnalisés</strong>${custom.map(view=>`<button role="menuitemradio" aria-checked="${active?.id===view.id}" data-admin="site-view-custom" data-value="${esc(view.id)}">${esc(view.name)}${db.adminDefaultSiteView===view.id?' · Par défaut':''}</button>`).join('')}`:''}<button role="menuitem" data-admin="site-view-save">Enregistrer la vue sous</button><button role="menuitem" data-admin="site-view-default" ${db.adminDefaultSiteView===defaultKey?'disabled':''}>Définir comme vue par défaut</button>${active?'<button role="menuitem" data-admin="site-view-delete">Supprimer cette vue</button>':''}<p>Les vues et leur réglage par défaut restent dans ce navigateur.</p></div>`:''}</div>`}
function siteViewSavePanel(){return state.adminSiteViewSaveOpen?`<div class="sp-nav-overlay"><aside class="sp-nav-editor" role="dialog" aria-modal="true" aria-labelledby="site-view-save-title"><div class="sp-panel-head"><h2 id="site-view-save-title">Enregistrer la vue sous</h2><button data-admin="site-view-save-close" aria-label="Fermer">×</button></div><p>Le tri, les filtres et les colonnes sont enregistrés dans ce navigateur. La recherche n’est pas incluse.</p><form id="admin-site-view-form"><label class="sp-field">Nom de la vue<input name="name" maxlength="100" required></label><p id="admin-site-view-error" role="alert"></p><button class="sp-primary">Enregistrer</button> <button type="button" data-admin="site-view-save-close">Annuler</button></form></aside></div>`:''}
function trackedSiteViews(){return Array.isArray(db.adminTrackedSiteViews)?db.adminTrackedSiteViews.filter(view=>view&&typeof view.key==='string'&&typeof view.name==='string'):[]}
function siteActivityMatches(site,filter,now=Date.now()){if(filter!=='last30')return true;const time=Date.parse(site.activity||'');return Number.isFinite(time)&&time<=now&&time>=now-30*86400000}
function siteMetadataValue(site,key){return String(site[key]||'')||'__empty__'}
function siteMetadataOptions(key,deleted){return [...new Set(db.sites.filter(site=>!!site.deleted===deleted).map(site=>siteMetadataValue(site,key)))].sort((a,b)=>a.localeCompare(b,'fr'))}
function siteMetadataFiltersMatch(site,owners,templates){return (!Array.isArray(owners)||!owners.length||owners.includes(siteMetadataValue(site,'owner')))&&(!Array.isArray(templates)||!templates.length||templates.includes(siteMetadataValue(site,'template')))}
function currentSiteViewSnapshot(){const custom=customSiteViews().find(view=>view.id===state.adminCustomSiteViewId),standard=siteViews.find(([id])=>id===(state.adminSiteView||'all'))||siteViews[0];return {key:custom?.id||'builtin:'+standard[0],name:custom?.name||standard[1],baseView:standard[0],teamsFilter:state.adminTeamsFilter||'',hubFilter:state.adminHubFilter||'',activityFilter:state.adminActivityFilter||'',owners:[...(state.adminOwnerFilters||[])],templates:[...(state.adminTemplateFilters||[])],sort:[...sortableSiteColumns,'sharingPopularity'].includes(state.adminSiteSort)?state.adminSiteSort:'name',sortDir:state.adminSiteSortDir==='desc'?'desc':'asc',columns:siteColumnPreferences()}}
function trackedSiteCount(view){return db.sites.filter(site=>!site.deleted&&siteInView(site,view.baseView||'all')&&siteMetadataFiltersMatch(site,view.owners,view.templates)&&siteActivityMatches(site,view.activityFilter)&&(!view.hubFilter||(view.hubFilter==='__empty__'?!siteHubKey(site):siteHubKey(site)===view.hubFilter))&&(!['connected','disconnected'].includes(view.teamsFilter)||!!site.teams===(view.teamsFilter==='connected'))).length}
function siteViewTrackPanel(){const view=state.adminSiteTrackDraft;if(!view)return '';return `<div class="sp-nav-overlay"><aside class="sp-nav-editor" role="dialog" aria-modal="true" aria-labelledby="site-view-track-title"><div class="sp-panel-head"><h2 id="site-view-track-title">Suivre la vue</h2><button data-admin="site-view-track-close" aria-label="Fermer">×</button></div><p>Ajouter une carte locale pour « ${esc(view.name)} » avec ${trackedSiteCount(view)} site(s) actif(s). Les données restent dans ce navigateur.</p><button class="sp-primary" data-admin="site-view-track-confirm">Ajouter la carte</button> <button data-admin="site-view-track-close">Annuler</button></aside></div>`}
function trackedSiteCards(){return trackedSiteViews().map(view=>`<section class="sp-card"><header>${esc(view.name)}</header><div class="sp-card-body"><h2>${trackedSiteCount(view)} site(s) actif(s)</h2><p class="sp-card-note">Vue suivie dans la simulation locale.</p><button data-admin="site-view-track-open" data-value="${esc(view.key)}">Afficher les sites</button> <button data-admin="site-view-track-remove" data-value="${esc(view.key)}">Retirer la carte</button></div></section>`).join('')}
function siteColumnPreferences(){const saved=state.adminViewColumnOverride||db.adminSiteColumns,valid=siteColumnDefinitions.map(([id])=>id),order=Array.isArray(saved?.order)?saved.order.filter((id,i,list)=>valid.includes(id)&&list.indexOf(id)===i):[];return {order:[...order,...valid.filter(id=>!order.includes(id))],hidden:Array.isArray(saved?.hidden)?saved.hidden.filter(id=>valid.includes(id)):[]}}
function siteColumnPanel(){if(!state.adminColumnsOpen)return '';const draft=state.adminColumnDraft,labels=Object.fromEntries(siteColumnDefinitions);return `<div class="sp-nav-overlay"><aside class="sp-access-panel sp-columns-panel" role="dialog" aria-modal="true" aria-labelledby="sp-columns-title"><div class="sp-panel-head"><h2 id="sp-columns-title">Personnalisation des colonnes</h2><button data-admin="columns-close" aria-label="Fermer">×</button></div><p>Sélectionnez les colonnes à afficher et utilisez les flèches pour modifier leur ordre.</p><form id="admin-columns-form"><div class="sp-columns-list">${draft.order.map((id,index)=>`<div><label><input type="checkbox" name="column" value="${esc(id)}" ${draft.hidden.includes(id)?'':'checked'}> ${esc(labels[id])}</label><span><button type="button" data-admin="column-up" data-value="${id}" aria-label="Monter ${esc(labels[id])}" ${index===0?'disabled':''}>↑</button><button type="button" data-admin="column-down" data-value="${id}" aria-label="Descendre ${esc(labels[id])}" ${index===draft.order.length-1?'disabled':''}>↓</button></span></div>`).join('')}</div><p id="admin-columns-error" role="alert"></p><footer><button class="sp-primary" type="submit">Appliquer</button> <button type="button" data-admin="columns-close">Annuler</button></footer></form></aside></div>`}
function siteHubLabel(site){if(site.isHub)return site.hubName||site.name;if(!site.hubSiteId)return '—';const hub=db.sites.find(item=>item.id===site.hubSiteId);return hub&&!hub.deleted&&hub.isHub?(hub.hubName||hub.name):'Hub indisponible'}
