function siteFileCount(site){return site.id==='contoso'?db.items.filter(item=>!item.deleted&&item.kind==='file').length:normalDocuments(site).filter(doc=>!doc.deleted&&doc.kind!=='folder').length}
function siteUsage30(site,now=Date.now()){const records=db.demoViews?.[site.id]||{},edits=site.demoFileEdits&&typeof site.demoFileEdits==='object'?site.demoFileEdits:{};const today=new Date(now).toISOString().slice(0,10),first=new Date(now-29*86400000).toISOString().slice(0,10);let tracked=false,pageViews=0;const pages=new Set(),files=new Set();for(const [id,entry] of Object.entries(records)){if(!entry?.days||typeof entry.days!=='object')continue;tracked=true;const count=Object.entries(entry.days).reduce((sum,[day,value])=>sum+(/^\d{4}-\d{2}-\d{2}$/.test(day)&&day>=first&&day<=today&&Number.isSafeInteger(value)&&value>0?value:0),0);if(!count)continue;if(id.startsWith('page:')){pageViews+=count;pages.add(id)}else files.add(id)}for(const [day,ids] of Object.entries(edits)){if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!Array.isArray(ids))continue;tracked=true;if(day>=first&&day<=today)for(const id of ids)if(typeof id==='string'&&id)files.add(id)}return tracked?{pageViews,pageVisits:pages.size,filesViewed:files.size}:null}
